/**
  \rst
  Returns a view that formats an integer value using ',' as a locale-independent
  thousands separator.

  **Example**::

    fmt::print("{}", fmt::group_digits(12345));
    // Output: "12,345"
  \endrst
 */
template <typename T> auto group_digits(T value) -> group_digits_view<T> {
  return {value};
}

template <typename T> struct formatter<group_digits_view<T>> : formatter<T> {
 private:
  detail::dynamic_format_specs<> specs_;

 public:
  template <typename ParseContext>
  FMT_CONSTEXPR auto parse(ParseContext& ctx) -> const char* {
    return parse_format_specs(ctx.begin(), ctx.end(), specs_, ctx,
                              detail::type::int_type);
  }

  template <typename Char, typename Out, typename C>
  auto apply(const detail::digit_grouping<Char>& grouping, Out out,
             basic_string_view<C> digits) const -> Out {
    auto num_digits = static_cast<int>(digits.size());
    auto separators = basic_memory_buffer<int>();
    separators.push_back(0);
    auto state = grouping.initial_state();
    while (int i = grouping.next(state)) {
      if (i >= num_digits) break;
      separators.push_back(i);
    }
    for (int i = 0, sep_index = static_cast<int>(separators.size() - 1);
         i < num_digits; ++i) {
      if (num_digits - i == separators[sep_index]) {
        auto sep = grouping.thousands_sep();
        out = detail::copy<Char>(sep.data(), sep.data() + sep.size(), out);
        --sep_index;
      }
      *out++ = static_cast<Char>(digits[detail::to_unsigned(i)]);
    }
    return out;
  }

  template <typename FormatContext>
  auto format(group_digits_view<T> t, FormatContext& ctx) const
      -> decltype(ctx.out()) {
    auto specs = specs_;
    detail::handle_dynamic_spec<detail::width_checker>(specs.width,
                                                       specs.width_ref, ctx);
    detail::handle_dynamic_spec<detail::precision_checker>(
        specs.precision, specs.precision_ref, ctx);
    auto grouping = detail::digit_grouping<char>("\3", ",");
    unsigned prefix = 0;
    auto abs_value = static_cast<detail::uint64_or_128_t<T>>(t.value);
    if (specs.type != presentation_type::none &&
        specs.type != presentation_type::dec) {
      return detail::write_int(ctx.out(), abs_value, prefix, specs, grouping);
    }
    int num_digits = detail::count_digits(abs_value);
    auto buffer = memory_buffer();
    detail::format_decimal<char>(appender(buffer), abs_value, num_digits);
    int extra_separators = 0;
    if (!grouping.thousands_sep().empty() && !grouping.grouping().empty())
      extra_separators = grouping.count_separators(num_digits);
    unsigned size = (prefix != 0 ? prefix >> 24 : 0) +
                    detail::to_unsigned(num_digits) +
                    detail::to_unsigned(extra_separators);
    return detail::write_padded<char, align::right>(
        ctx.out(), specs, size, size,
        [&](detail::reserve_iterator<decltype(ctx.out())> it) {
          for (unsigned p = prefix & 0xffffff; p != 0; p >>= 8)
            *it++ = static_cast<char>(p & 0xff);
          return apply(grouping, it, string_view(buffer.data(), buffer.size()));
        });
  }
};

