template <typename Char, typename Out, typename C>
auto apply_grouping(const digit_grouping<Char>& grouping, Out out,
                    basic_string_view<C> digits) -> Out {
  return formatter<group_digits_view<int>>{}.apply(grouping, out, digits);
}
